{"command":"cat <<'EOF' > lintname.py
import re

initialisms = {
    "ACL", "API", "ASCII", "CPU", "CSS", "DNS", "EOF", "GUID", "HTML", "HTTP",
    "HTTPS", "ID", "IP", "JSON", "LHS", "QPS", "RAM", "RHS", "RPC", "SLA",
    "SMTP", "SQL", "SSH", "TCP", "TLS", "TTL", "UDP", "UI", "UID", "UUID",
    "URI", "URL", "UTF8", "VM", "XML", "XMPP", "XSRF", "XSS"
}

def lint_name(name):
    if name == "_": return name
    if "_" not in name: return name

    # Check ALL_CAPS
    # ALL_CAPS means uppercase letters and underscores (and digits)
    if name == name.upper() and "_" in name:
        # wait, only if it has letters
        if re.search(r'[A-Z]', name):
            return "ALL_CAPS"

    # Remove leading and trailing underscores, but remember leading one
    original = name
    parts = original.split("_")

    # We must construct camel case
    # wait, golint's logic:
    runes = list(name)
    if not runes: return ""

    # just split by _
    words = []
    current = []
    for r in runes:
        if r == "_":
            words.append("".join(current))
            current = []
        else:
            current.append(r)
    words.append("".join(current))

    # wait, actual golint algorithm is:
    # return the camelcased name
    out = ""
    for i, w in enumerate(words):
        if w == "":
            if i == 0:
                out += "_"
            continue
        u = w.upper()
        if u in initialisms:
            if i == 0 and name[0].islower():
                out += w.lower()
            else:
                out += u
        else:
            if i > 0 or (out != "" and out[-1] != '_'):
                out += w[0].upper() + w[1:]
            else:
                out += w
    return out

cases = [
    "http_server", "my_http_server", "API_server", "___bad_name",
    "Http_server", "my_url_path", "Url_path", "My_api_key",
    "id_user", "Id_user", "my_Id_user", "my_ID_user", "user_id",
    "My_var", "my_var", "mY_vAr", "MY_VAR", "MY_VAR_123",
    "_a", "a_", "_a_b_", "__", "___a", "____a", "_a_"
]

for c in cases:
    print(f"{c:15} -> {lint_name(c)}")
EOF
python3 lintname.py
"}

