{"command":"cat <<'EOF' > build_linter.go
package main

import (
	"bytes"
	"encoding/json"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"os"
	"path/filepath"
	"strings"
	"unicode"
)

type Position struct {
	Start struct {
		Filename string
		Offset   int
		Line     int
		Column   int
	}
	End struct {
		Filename string
		Offset   int
		Line     int
		Column   int
	}
}

type Issue struct {
	Severity        string
	Failure         string
	RuleName        string
	Category        string
	Position        Position
	Confidence      float64
	ReplacementLine string
}

var fset = token.NewFileSet()
var issues []Issue

func addIssue(failure, rule, cat string, conf float64, start, end token.Pos) {
	sPos := fset.Position(start)
	ePos := fset.Position(end)
	issues = append(issues, Issue{
		Severity: "warning",
		Failure:  failure,
		RuleName: rule,
		Category: cat,
		Position: Position{
			Start: struct{Filename string; Offset int; Line int; Column int}{Filename: sPos.Filename, Offset: sPos.Offset, Line: sPos.Line, Column: sPos.Column},
			End:   struct{Filename string; Offset int; Line int; Column int}{Filename: ePos.Filename, Offset: ePos.Offset, Line: ePos.Line, Column: ePos.Column},
		},
		Confidence:      conf,
		ReplacementLine: "",
	})
}

var initialisms = map[string]bool{
	"ACL": true, "API": true, "ASCII": true, "CPU": true, "CSS": true, "DNS": true,
	"EOF": true, "GUID": true, "HTML": true, "HTTP": true, "HTTPS": true, "ID": true,
	"IP": true, "JSON": true, "LHS": true, "QPS": true, "RAM": true, "RHS": true,
	"RPC": true, "SLA": true, "SMTP": true, "SQL": true, "SSH": true, "TCP": true,
	"TLS": true, "TTL": true, "UDP": true, "UI": true, "UID": true, "UUID": true,
	"URI": true, "URL": true, "UTF8": true, "VM": true, "XML": true, "XMPP": true,
	"XSRF": true, "XSS": true,
}

func lintName(name string) string {
	if name == "_" {
		return name
	}
	allLower := true
	for _, r := range name {
		if !unicode.IsLower(r) {
			allLower = false
			break
		}
	}
	if allLower {
		return name
	}
	runes := []rune(name)
	w, i := 0, 0
	for i+1 <= len(runes) {
		eow := false
		if i+1 == len(runes) {
			eow = true
		} else if runes[i+1] == '_' {
			eow = true
			n := 1
			for i+n+1 < len(runes) && runes[i+n+1] == '_' {
				n++
			}
			if i+n+1 < len(runes) && unicode.IsDigit(runes[i]) && unicode.IsDigit(runes[i+n+1]) {
				n--
			}
			copy(runes[i+1:], runes[i+n+1:])
			runes = runes[:len(runes)-n]
		} else if unicode.IsLower(runes[i]) && !unicode.IsLower(runes[i+1]) {
			eow = true
		}
		i++
		if !eow {
			continue
		}
		word := string(runes[w:i])
		if u := strings.ToUpper(word); initialisms[u] {
			if w == 0 && unicode.IsLower(runes[w]) {
				u = strings.ToLower(u)
			}
			copy(runes[w:], []rune(u))
		} else if w > 0 && strings.ToLower(word) == word {
			runes[w] = unicode.ToUpper(runes[w])
		}
		w = i
	}
	return string(runes)
}

func checkName(id *ast.Ident, kind string) {
	if id == nil || id.Name == "_" {
		return
	}
	if strings.Contains(id.Name, "_") {
		allCaps := true
		for _, r := range id.Name {
			if !unicode.IsUpper(r) && !unicode.IsDigit(r) && r != '_' {
				allCaps = false
				break
			}
		}
		if allCaps && len(id.Name) > 5 {
			addIssue("don't use ALL_CAPS in Go names; use CamelCase", "var-naming", "naming", 0.8, id.Pos(), id.End())
			return
		}
	}
	ln := lintName(id.Name)
	if ln != id.Name {
		addIssue(fmt.Sprintf("don't use underscores in Go names; %s %s should be %s", kind, id.Name, ln), "var-naming", "naming", 0.9, id.Pos(), id.End())
	}
}

func typeStr(node ast.Expr) string {
	var buf bytes.Buffer
	printer.Fprint(token.NewFileSet(), &buf, node)
	return buf.String()
}

func visit(node ast.Node) bool {
	if node == nil {
		return true
	}
	switch n := node.(type) {
	case *ast.GenDecl:
		if n.Tok == token.VAR || n.Tok == token.CONST {
			kind := "var"
			if n.Tok == token.CONST {
				kind = "const"
			}
			for _, spec := range n.Specs {
				vspec := spec.(*ast.ValueSpec)
				for _, id := range vspec.Names {
					checkName(id, kind)
				}
				if n.Tok == token.VAR && vspec.Type != nil && len(vspec.Values) > 0 {
					lhsType := typeStr(vspec.Type)
					for _, val := range vspec.Values {
						infer := false
						switch v := val.(type) {
						case *ast.BasicLit:
							switch v.Kind {
							case token.INT:
								infer = lhsType == "int"
							case token.FLOAT:
								infer = lhsType == "float64"
							case token.IMAG:
								infer = lhsType == "complex128"
							case token.CHAR:
								infer = lhsType == "rune"
							case token.STRING:
								infer = lhsType == "string"
							}
						case *ast.CompositeLit:
							infer = lhsType == typeStr(v.Type)
						case *ast.CallExpr:
							infer = lhsType == typeStr(v.Fun)
						case *ast.Ident:
							if v.Name == "true" || v.Name == "false" {
								infer = lhsType == "bool"
							}
						}
						if infer {
							addIssue(fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", lhsType, vspec.Names[0].Name), "var-declaration", "type-inference", 0.8, vspec.Names[0].Pos(), vspec.Names[0].End())
						}
					}
				}
			}
		} else if n.Tok == token.TYPE {
			for _, spec := range n.Specs {
				tspec := spec.(*ast.TypeSpec)
				checkName(tspec.Name, "type")
			}
		}
	case *ast.StructType:
		for _, f := range n.Fields.List {
			for _, id := range f.Names {
				checkName(id, "struct field")
			}
		}
	case *ast.FuncDecl:
		kind := "func"
		if n.Recv != nil {
			kind = "method"
			// Check receiver name
			if len(n.Recv.List) > 0 {
				if len(n.Recv.List[0].Names) > 0 {
					recvName := n.Recv.List[0].Names[0].Name
					if recvName == "this" || recvName == "self" {
						addIssue(`receiver name should be a reflection of its identity; don't use generic names such as "this" or "self"`, "receiver-naming", "naming", 1, n.Pos(), n.End())
					}
				}
			}
		}
		checkName(n.Name, kind)

        // Context first
        if n.Type.Params != nil && len(n.Type.Params.List) > 0 {
            for i, p := range n.Type.Params.List {
                if typeStr(p.Type) == "context.Context" && i > 0 {
                    addIssue("context.Context should be the first parameter of a function", "context-as-argument", "arg-order", 0.9, p.Pos(), p.End())
                }
            }
        }

        // Error last
        if n.Type.Results != nil && len(n.Type.Results.List) > 1 {
            for i, res := range n.Type.Results.List {
                if typeStr(res.Type) == "error" && i < len(n.Type.Results.List)-1 {
                    addIssue("error should be the last type when returning multiple items", "error-return", "style", 0.9, n.Pos(), n.End())
                }
            }
        }

        // Unused parameter - Wait, does the executable flag unused parameters?
        // Yes, in other_rules.go it flagged i and ctx as unused!
        // We will implement unused parameter check by collecting param names and checking if they are used in Body.
        if n.Body != nil {
            used := make(map[string]bool)
            ast.Inspect(n.Body, func(bn ast.Node) bool {
                if id, ok := bn.(*ast.Ident); ok {
                    used[id.Name] = true
                }
                return true
            })
            if n.Type.Params != nil {
                for _, p := range n.Type.Params.List {
                    for _, id := range p.Names {
                        if id.Name != "_" && !used[id.Name] {
                            addIssue(fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", id.Name), "unused-parameter", "bad practice", 1, id.Pos(), id.End())
                        }
                    }
                }
            }
        }

	case *ast.IfStmt:
		if len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
		if n.Else != nil {
			if el, ok := n.Else.(*ast.BlockStmt); ok && len(el.List) == 0 {
				addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, el.Pos(), el.End())
			}
		}
	case *ast.ForStmt:
		if len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
	case *ast.RangeStmt:
		if len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
	case *ast.SwitchStmt:
		if len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
	case *ast.TypeSwitchStmt:
		if len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}

    // Error strings
    case *ast.CallExpr:
        fun := typeStr(n.Fun)
        if fun == "errors.New" || fun == "fmt.Errorf" {
            if len(n.Args) > 0 {
