	var setExitStatus bool
	var version bool

	flag.StringVar(&config, "config", "", "path to the configuration TOML file")
	flag.StringVar(&exclude, "exclude", "", "list of globs which specify files to be excluded")
	flag.StringVar(&formatter, "formatter", "default", "formatter to be used for the output")
	flag.IntVar(&maxOpenFiles, "max_open_files", 0, "maximum number of open files at the same time")
