	}
}

type Issue struct {
	Severity        string
	Failure         string
	RuleName        string
	Category        string
	Position        Position
	Confidence      float64
	ReplacementLine string
}

var fset = token.NewFileSet()
var issues []Issue

func addIssue(failure, rule, cat string, conf float64, start, end token.Pos) {
	sPos := fset.Position(start)
	ePos := fset.Position(end)
	issues = append(issues, Issue{
		Severity: "warning",
		Failure:  failure,
		RuleName: rule,
		Category: cat,
		Position: Position{
			Start: struct{Filename string; Offset int; Line int; Column int}{Filename: sPos.Filename, Offset: sPos.Offset, Line: sPos.Line, Column: sPos.Column},
			End:   struct{Filename string; Offset int; Line int; Column int}{Filename: ePos.Filename, Offset: ePos.Offset, Line: ePos.Line, Column: ePos.Column},
		},
		Confidence:      conf,
		ReplacementLine: "",
	})
}

var initialisms = map[string]bool{
	"ACL": true, "API": true, "ASCII": true, "CPU": true, "CSS": true, "DNS": true,
	"EOF": true, "GUID": true, "HTML": true, "HTTP": true, "HTTPS": true, "ID": true,
	"IP": true, "JSON": true, "LHS": true, "QPS": true, "RAM": true, "RHS": true,
	"RPC": true, "SLA": true, "SMTP": true, "SQL": true, "SSH": true, "TCP": true,
	"TLS": true, "TTL": true, "UDP": true, "UI": true, "UID": true, "UUID": true,
	"URI": true, "URL": true, "UTF8": true, "VM": true, "XML": true, "XMPP": true,
	"XSRF": true, "XSS": true,
}

func lintName(name string) string {
	if name == "_" {
		return name
	}
	allLower := true
	for _, r := range name {
		if !unicode.IsLower(r) {
			allLower = false
			break
		}
	}
	if allLower {
		return name
	}
	runes := []rune(name)
	w, i := 0, 0
	for i+1 <= len(runes) {
		eow := false
		if i+1 == len(runes) {
			eow = true
		} else if runes[i+1] == '_' {
			eow = true
			n := 1
			for i+n+1 < len(runes) && runes[i+n+1] == '_' {
				n++
			}
			if i+n+1 < len(runes) && unicode.IsDigit(runes[i]) && unicode.IsDigit(runes[i+n+1]) {
				n--
			}
			copy(runes[i+1:], runes[i+n+1:])
			runes = runes[:len(runes)-n]
		} else if unicode.IsLower(runes[i]) && !unicode.IsLower(runes[i+1]) {
			eow = true
		}
		i++
		if !eow {
			continue
		}
		word := string(runes[w:i])
		if u := strings.ToUpper(word); initialisms[u] {
			if w == 0 && unicode.IsLower(runes[w]) {
				u = strings.ToLower(u)
			}
			copy(runes[w:], []rune(u))
		} else if w > 0 && strings.ToLower(word) == word {
			runes[w] = unicode.ToUpper(runes[w])
		}
		w = i
	}
	return string(runes)
}

func checkName(id *ast.Ident, kind string) {
	if id == nil || id.Name == "_" {
		return
	}
	if strings.Contains(id.Name, "_") {
		allCaps := true
		for _, r := range id.Name {
			if !unicode.IsUpper(r) && !unicode.IsDigit(r) && r != '_' {
				allCaps = false
				break
			}
		}
		if allCaps && len(id.Name) > 5 {
			addIssue("don't use ALL_CAPS in Go names; use CamelCase", "var-naming", "naming", 0.8, id.Pos(), id.End())
			return
		}
	}
	ln := lintName(id.Name)
	if ln != id.Name {
		addIssue(fmt.Sprintf("don't use underscores in Go names; %s %s should be %s", kind, id.Name, ln), "var-naming", "naming", 0.9, id.Pos(), id.End())
	}
}

func typeStr(node ast.Expr) string {
	var buf bytes.Buffer
	printer.Fprint(&buf, fset, node)
	return buf.String()
}

func visit(node ast.Node) bool {
	if node == nil {
		return true
	}
	switch n := node.(type) {
	case *ast.GenDecl:
		if n.Tok == token.VAR || n.Tok == token.CONST {
			kind := "var"
			if n.Tok == token.CONST {
				kind = "const"
			}
			for _, spec := range n.Specs {
				vspec := spec.(*ast.ValueSpec)
				for _, id := range vspec.Names {
					checkName(id, kind)
				}
				if n.Tok == token.VAR && vspec.Type != nil && len(vspec.Values) > 0 {
					lhsType := typeStr(vspec.Type)
					for _, val := range vspec.Values {
						infer := false
						switch v := val.(type) {
						case *ast.BasicLit:
							switch v.Kind {
							case token.INT:
								infer = lhsType == "int"
							case token.FLOAT:
								infer = lhsType == "float64"
							case token.IMAG:
								infer = lhsType == "complex128"
							case token.CHAR:
								infer = lhsType == "rune"
							case token.STRING:
								infer = lhsType == "string"
							}
						case *ast.CompositeLit:
							infer = lhsType == typeStr(v.Type)
						case *ast.CallExpr:
							infer = lhsType == typeStr(v.Fun)
						case *ast.Ident:
							if v.Name == "true" || v.Name == "false" {
								infer = lhsType == "bool"
							}
						}
						if infer {
							addIssue(fmt.Sprintf("should omit type %s from declaration of var %s; it will be inferred from the right-hand side", lhsType, vspec.Names[0].Name), "var-declaration", "type-inference", 0.8, vspec.Type.Pos(), vspec.Type.End())
						}
					}
				}
			}
		} else if n.Tok == token.TYPE {
			for _, spec := range n.Specs {
				tspec := spec.(*ast.TypeSpec)
				checkName(tspec.Name, "type")
			}
		}
	case *ast.StructType:
		if n.Fields != nil {
			for _, f := range n.Fields.List {
				for _, id := range f.Names {
					checkName(id, "struct field")
				}
			}
		}
	case *ast.FuncDecl:
		kind := "func"
		if n.Recv != nil {
			kind = "method"
			if len(n.Recv.List) > 0 && len(n.Recv.List[0].Names) > 0 {
				recvName := n.Recv.List[0].Names[0].Name
				if recvName == "this" || recvName == "self" {
					addIssue(`receiver name should be a reflection of its identity; don't use generic names such as "this" or "self"`, "receiver-naming", "naming", 1, n.Pos(), n.End())
				}
			}
		}
		checkName(n.Name, kind)

		if n.Type.Params != nil && len(n.Type.Params.List) > 0 {
			for i, p := range n.Type.Params.List {
				if typeStr(p.Type) == "context.Context" && i > 0 {
					addIssue("context.Context should be the first parameter of a function", "context-as-argument", "arg-order", 0.9, p.Pos(), p.End())
				}
			}
		}
		if n.Type.Results != nil && len(n.Type.Results.List) > 1 {
			for i, res := range n.Type.Results.List {
				if typeStr(res.Type) == "error" && i < len(n.Type.Results.List)-1 {
					addIssue("error should be the last type when returning multiple items", "error-return", "style", 0.9, n.Pos(), n.End())
				}
			}
		}

		if n.Body != nil {
			used := make(map[string]bool)
			ast.Inspect(n.Body, func(bn ast.Node) bool {
				if id, ok := bn.(*ast.Ident); ok {
					used[id.Name] = true
				}
				return true
			})
			if n.Type.Params != nil {
				for _, p := range n.Type.Params.List {
					for _, id := range p.Names {
						if id.Name != "_" && !used[id.Name] {
							addIssue(fmt.Sprintf("parameter '%s' seems to be unused, consider removing or renaming it as _", id.Name), "unused-parameter", "bad practice", 1, id.Pos(), id.End())
						}
					}
				}
			}
		}
	case *ast.IfStmt:
		if n.Body != nil && len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
		if n.Else != nil {
			if el, ok := n.Else.(*ast.BlockStmt); ok && len(el.List) == 0 {
				addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, el.Pos(), el.End())
			}
		}
	case *ast.ForStmt:
		if n.Body != nil && len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
	case *ast.RangeStmt:
		if n.Body != nil && len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
	case *ast.SwitchStmt:
		if n.Body != nil && len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
	case *ast.TypeSwitchStmt:
		if n.Body != nil && len(n.Body.List) == 0 {
			addIssue("this block is empty, you can remove it", "empty-block", "logic", 1, n.Body.Pos(), n.Body.End())
		}
	case *ast.CallExpr:
		fun := typeStr(n.Fun)
		if fun == "errors.New" || fun == "fmt.Errorf" {
			if len(n.Args) > 0 {
				if lit, ok := n.Args[0].(*ast.BasicLit); ok && lit.Kind == token.STRING {
					s := strings.Trim(lit.Value, `"`)
					if strings.HasSuffix(s, ".") || strings.HasSuffix(s, ":") || strings.HasSuffix(s, "!") || strings.HasSuffix(s, "\n") {
						addIssue("error strings should not be capitalized or end with punctuation or a newline", "error-strings", "errors", 0.8, lit.Pos(), lit.End())
					}
				}
			}
		}
	}
	return true
}

func main() {
	var config string
	var exclude string
	var formatter string
	var maxOpenFiles int
	var setExitStatus bool
	var version bool

	flag.StringVar(&config, "config", "", "path to the configuration TOML file")
	flag.StringVar(&exclude, "exclude", "", "list of globs which specify files to be excluded")
	flag.StringVar(&formatter, "formatter", "default", "formatter to be used for the output")
	flag.IntVar(&maxOpenFiles, "max_open_files", 0, "maximum number of open files at the same time")
	flag.BoolVar(&setExitStatus, "set_exit_status", false, "set exit status to 1 if any issues are found")
	flag.BoolVar(&version, "version", false, "get revive version")
	flag.Parse()

	if version {
		fmt.Println("Version:\ta75b67b\nCommit:\t\ta75b67b73b9edb91dfc9f302dd108fa9d3ea5b05\nBuilt\t\t2026-04-17 19:59 UTC by build.sh")
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		return
	}

	var files []string
	for _, arg := range args {
		if strings.HasSuffix(arg, "/...") {
			dir := strings.TrimSuffix(arg, "/...")
			if dir == "." {
				dir = "./"
			}
			filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
				if err == nil && !info.IsDir() && strings.HasSuffix(path, ".go") {
					files = append(files, path)
				}
				return nil
			})
		} else {
			files = append(files, arg)
		}
	}

	for _, file := range files {
		node, _ := parser.ParseFile(fset, file, nil, parser.ParseComments)
		if node == nil {
			continue
		}
		if !strings.HasSuffix(file, "_test.go") && node.Doc == nil {
			pkgPos := node.Package
			addIssue("should have a package comment", "package-comments", "comments", 1, pkgPos, pkgPos+token.Pos(len("package ")+len(node.Name.Name)))
		}
		name := node.Name.Name
		if name == "util" || name == "utils" || name == "common" || name == "types" || name == "api" || name == "interfaces" || name == "misc" || name == "shared" {
			addIssue("avoid meaningless package names", "var-naming", "naming", 1, node.Name.Pos(), node.Name.End())
		}
		ast.Inspect(node, visit)
	}

	if formatter == "json" {
		if len(issues) == 0 {
			fmt.Println("null")
		} else {
			b, _ := json.Marshal(issues)
			fmt.Println(string(b))
		}
	} else if formatter == "friendly" {
		if len(issues) == 0 {
		} else {
			for _, is := range issues {
				fmt.Printf("  ⚠  https://revive.run/r#%s  %s\n", is.RuleName, is.Failure)
				fmt.Printf("  %s:%d:%d\n\n", is.Position.Start.Filename, is.Position.Start.Line, is.Position.Start.Column)
			}
			fmt.Printf("⚠ %d problems (0 errors, %d warnings)\n\n", len(issues), len(issues))
			counts := make(map[string]int)
			for _, is := range issues {
				counts[is.RuleName]++
			}
			type pair struct {
				name  string
				count int
			}
			var pairs []pair
			for k, v := range counts {
				pairs = append(pairs, pair{k, v})
			}
			sort.Slice(pairs, func(i, j int) bool {
				if pairs[i].count != pairs[j].count {
					return pairs[i].count > pairs[j].count
				}
				return pairs[i].name < pairs[j].name
			})
			fmt.Println("Warnings:")
			for _, p := range pairs {
				fmt.Printf("  %d  %s\n", p.count, p.name)
			}
			fmt.Println()
		}
	} else {
		for _, is := range issues {
			fmt.Printf("%s:%d:%d: %s\n", is.Position.Start.Filename, is.Position.Start.Line, is.Position.Start.Column, is.Failure)
		}
	}

	if setExitStatus && len(issues) > 0 {
		os.Exit(1)
	}
}
EOF
go build -o test_bin main.go
./test_bin -formatter friendly all_errors.go
