	flag.IntVar(&maxOpenFiles, "max_open_files", 0, "maximum number of open files at the same time")
	flag.BoolVar(&setExitStatus, "set_exit_status", false, "set exit status to 1 if any issues are found")
	flag.BoolVar(&version, "version", false, "get revive version")
	flag.Parse()

	if version {
		fmt.Println("Version:\ta75b67b\nCommit:\t\ta75b67b73b9edb91dfc9f302dd108fa9d3ea5b05\nBuilt\t\t2026-04-17 19:59 UTC by build.sh")
		return
	}

	args := flag.Args()
	if len(args) == 0 {
		return
	}

	var files []string
	for _, arg := range args {
		if strings.HasSuffix(arg, "/...") {
			dir := strings.TrimSuffix(arg, "/...")
			if dir == "." {
				dir = "./"
			}
			filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
				if err == nil && !info.IsDir() && strings.HasSuffix(path, ".go") {
					files = append(files, path)
				}
				return nil
			})
		} else {
			files = append(files, arg)
		}
	}

	for _, file := range files {
		node, _ := parser.ParseFile(fset, file, nil, parser.ParseComments)
		if node == nil {
			continue
		}
		if !strings.HasSuffix(file, "_test.go") && node.Doc == nil {
			pkgPos := node.Package
			addIssue("should have a package comment", "package-comments", "comments", 1, pkgPos, pkgPos+token.Pos(len("package ")+len(node.Name.Name)))
		}
		name := node.Name.Name
		if name == "util" || name == "utils" || name == "common" || name == "types" || name == "api" || name == "interfaces" || name == "misc" || name == "shared" {
			addIssue("avoid meaningless package names", "var-naming", "naming", 1, node.Name.Pos(), node.Name.End())
		}
		ast.Inspect(node, visit)
	}

	if formatter == "json" {
		if len(issues) == 0 {
			fmt.Println("null")
		} else {
			b, _ := json.Marshal(issues)
			fmt.Println(string(b))
		}
	} else if formatter == "friendly" {
		if len(issues) == 0 {
		} else {
			for _, is := range issues {
				fmt.Printf("  ⚠  https://revive.run/r#%s  %s\n", is.RuleName, is.Failure)
				fmt.Printf("  %s:%d:%d\n\n", is.Position.Start.Filename, is.Position.Start.Line, is.Position.Start.Column)
			}
			fmt.Printf("⚠ %d problems (0 errors, %d warnings)\n\n", len(issues), len(issues))
			counts := make(map[string]int)
			for _, is := range issues {
				counts[is.RuleName]++
			}
			type pair struct {
				name  string
				count int
			}
			var pairs []pair
			for k, v := range counts {
				pairs = append(pairs, pair{k, v})
			}
			sort.Slice(pairs, func(i, j int) bool {
				if pairs[i].count != pairs[j].count {
					return pairs[i].count > pairs[j].count
				}
				return pairs[i].name < pairs[j].name
			})
			fmt.Println("Warnings:")
			for _, p := range pairs {
				fmt.Printf("  %d  %s\n", p.count, p.name)
			}
			fmt.Println()
		}
	} else {
		for _, is := range issues {
			fmt.Printf("%s:%d:%d: %s\n", is.Position.Start.Filename, is.Position.Start.Line, is.Position.Start.Column, is.Failure)
		}
	}

	if setExitStatus && len(issues) > 0 {
		os.Exit(1)
	}
}
EOF
go build -o test_bin main.go
./test_bin -formatter friendly all_errors.go
"}

