# find `for _, file := range files {`
exclude_logic = """	for _, file := range files {
		excluded := false
		for _, excl := range excludeFlags {
			if excl == file { excluded = true; break }
			if strings.HasSuffix(excl, "/...") {
				dir := strings.TrimSuffix(excl, "/...")
				if strings.HasPrefix(file, dir+"/") { excluded = true; break }
			} else {
				match, _ := filepath.Match(excl, file)
				if match { excluded = true; break }
			}
		}
		if excluded { continue }
"""
content = content.replace('	for _, file := range files {', exclude_logic)

with open("main.go", "w") as f:
    f.write(content)
